81			return nil, nil
82		}
83		lastEntry := entries[len(entries)-1]
84		lastPersistedMessage := &protos.SavedMessage{}
85		if err := proto.Unmarshal(lastEntry, lastPersistedMessage); err != nil {
86			ps.Logger.Errorf("Failed unmarshaling last entry from WAL: %v", err)
87			return nil, fmt.Errorf("failed unmarshaling last entry from WAL: %w", err)
88		}
89		if newViewMsg := lastPersistedMessage.GetNewView(); newViewMsg != nil {
90			ps.Logger.Infof("last entry in WAL is a newView record")
91			return &types.ViewAndSeq{View: newViewMsg.ViewId, Seq: newViewMsg.LatestSequence}, nil
92		}
