54	// dirReadWalNames finds file names that follow the wal file name template.
55	func dirReadWalNames(dirPath string) ([]string, error) {
56		dirFile, err := os.Open(dirPath)
57		if err != nil {
58			return nil, err
59		}
60		defer dirFile.Close()
61	
62		names, err := dirFile.Readdirnames(-1)
63		if err != nil {
64			return nil, err
65		}
66	
67		walNames := make([]string, 0)
68	
69		for _, name := range names {
70			if strings.HasSuffix(name, walFileSuffix) {
71				var index uint64
72	
73				n, err := fmt.Sscanf(name, walFileTemplate, &index)
74				if n != 1 || err != nil {
75					continue
76				}
77	
78				walNames = append(walNames, name)
79			}
80		}
81	
82		sort.Strings(walNames)
83	
84		return walNames, nil
85	}
