87	// checkWalFiles for continuous sequence, readable CRC-Anchor.
88	// If the last file cannot be read, it may be ignored,  (or repaired).
89	func checkWalFiles(logger api.Logger, dirName string, walNames []string) ([]uint64, error) {
90		sort.Strings(walNames)
91	
92		indexes := make([]uint64, 0)
93	
94		for i, name := range walNames {
95			index, err := parseWalFileName(name)
96			if err != nil {
97				logger.Errorf("wal: failed to parse file name: %s; error: %s", name, err)
98	
99				return nil, err
100			}
101	
102			indexes = append(indexes, index)
103	
104			// verify we have CRC-Anchor.
105			r, err := NewLogRecordReader(logger, filepath.Join(dirName, walNames[i]))
106			if err != nil {
107				// check if it is the last file and return a special error that allows a repair.
108				if i == len(walNames)-1 {
109					logger.Errorf(
110						"wal: failed to create reader for last file: %s; error: %s; this may possibly be repaired.",
111						name,
112						err,
113					)
114	
115					return nil, io.ErrUnexpectedEOF
116				}
117	
118				return nil, fmt.Errorf("wal: failed to create reader for file: %s; error: %w", name, err)
119			}
120	
121			err = r.Close()
122			if err != nil {
123				return nil, fmt.Errorf("wal: failed to close reader for file: %s; error: %w", name, err)
124			}
125	
126			// verify no gaps
127			if i == 0 {
128				continue
129			}
130	
131			if index != (indexes[i-1] + 1) {
132				return nil, errors.New("wal: files not in sequence")
133			}
134		}
135	
136		slices.Sort(indexes)
137	
138		return indexes, nil
139	}
