185	// scanVerifyFiles.
186	func scanVerifyFiles(logger api.Logger, dirPath string, files []string) error {
187		var (
188			crc           uint32
189			num, numTotal int
190		)
191	
192		for i, name := range files {
193			fullName := filepath.Join(dirPath, name)
194	
195			r, err := NewLogRecordReader(logger, fullName)
196			if err != nil {
197				return err
198			}
199	
200			if num, err = scanVerify1(logger, r, i, crc); err != nil {
201				return err
202			}
203	
204			numTotal += num
205			crc = r.crc // final CRC of file
206		}
207	
208		logger.Debugf("Scanned %d records in %d files", numTotal, len(files))
209	
210		return nil
211	}
