213	func scanVerify1(logger api.Logger, r *LogRecordReader, i int, crc uint32) (num int, err error) {
214		defer func() { _ = r.Close() }()
215	
216		if i > 0 && crc != r.crc {
217			logger.Errorf("Anchor-CRC %08X of file: %s, does not match previous: %08X", r.crc, r.logFile.Name(), crc)
218	
219			return 0, ErrCRC
220		}
221	
222		var readErr error
223		for readErr == nil {
224			num++
225	
226			_, readErr = r.Read()
227		}
228	
229		if !errors.Is(readErr, io.EOF) {
230			return num - 1, readErr
231		}
232	
233		return num - 1, nil
234	}
