236	// scanRepairFile scans the file to the last good record and truncates after it. If even the CRC-Anchor cannot be
237	// read, the file is deleted.
238	func scanRepairFile(logger api.Logger, lastFile string) error {
239		logger.Debugf("Trying to repair file: %s", lastFile)
240	
241		r, err := NewLogRecordReader(logger, lastFile)
242		if err != nil {
243			logger.Warnf("Write-Ahead-Log could not open the last file, due to error: %s", err)
244	
245			if err = os.Remove(lastFile); err != nil {
246				return err
247			}
248	
249			logger.Warnf("Write-Ahead-Log DELETED the last file (a copy was saved): %s", lastFile)
250	
251			return nil
252		}
253	
254		// scan to the last good record
255		offset, err := r.logFile.Seek(0, io.SeekCurrent)
256		if err != nil {
257			_ = r.Close()
258	
259			return err
260		}
261	
262		num := 0
263	
264		for {
265			_, readErr := r.Read()
266			if readErr != nil {
267				logger.Debugf("Read error: %s", readErr)
268	
269				if closeErr := r.Close(); closeErr != nil {
270					return closeErr
271				}
272	
273				if errors.Is(readErr, io.EOF) {
274					logger.Debugf("Read %d good records till EOF, no need to repair", num)
275	
276					return nil // no need to repair
277				}
278	
279				break
280			}
281			// keep the end offset of a good record
282			num++
283	
284			offset, err = r.logFile.Seek(0, io.SeekCurrent)
285			if err != nil {
286				return err
287			}
